<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import ChannelEditor from './ChannelEditor.vue'
import ChannelNodeSelect from './ChannelNodeSelect.vue'
import {protectedChannel} from './channelActions'
import ModelPicker from './ModelPicker.vue'
import NewChannelDialog from './NewChannelDialog.vue'
import NativeConfigImportDialog from './NativeConfigImportDialog.vue'
import FileSourceReview from './FileSourceReview.vue'
import {useModelSaveFeedback} from '@/app/feedback/modelSave'
import {useFeedbackStore} from '@/app/feedback/store'
import {useModalStore} from '@/app/modal/store'
import {useModelsV2Store} from './store-v2'
import {channelNameErrorV2} from './channelRename'
const props=withDefaults(defineProps<{actionsTarget?:string;active?:boolean}>(),{active:true})
const models=useModelsV2Store(),nodeOpenId=ref(''),selectedChannelIds=ref<string[]>([]),newChannelOpen=ref(false),importOpen=ref(false),saveOpen=ref(false),pickerOpen=ref(false),copyId=ref(''),copyName=ref(''),reuseCopyKey=ref(false),copyError=ref(''),deleteId=ref(''),saveScope=ref<string|undefined>()
const editor=computed(()=>models.channels.find(c=>c.id===models.channelEditorId))
const filtered=computed(()=>models.channels.filter(c=>(c.label+' '+c.id).toLowerCase().includes(models.channelSearch.toLowerCase())))
const nameErrors=computed(()=>models.channels.map(c=>channelNameErrorV2(c.label,c.id,models.channels)).filter(Boolean))
let reviewBase=''
function currentReview(){return JSON.stringify({scope:saveScope.value,credentialInputRevision:models.credentialInputRevision,base:models.file?.draft?.base,source:models.file?.sourceDigest,library:models.file?.libraryDigest,channelIntents:models.channelIntents,edits:models.modelEdits})}
function prepareSave(scope?:string){if(props.active===false||!models.canSaveFile||models.pendingRows.length||nameErrors.value.length||!scope&&!!editor.value)return;if(scope&&!models.channelIntents.some(i=>i.channelId===scope&&(i.kind==='rename'||i.kind==='delete'))){const channel=models.channels.find(c=>c.id===scope);if(channel)models.queueChannel({kind:'rename',channelId:scope,name:channel.label})}saveScope.value=models.channelCapabilities.scopedSave?scope:undefined;reviewBase=currentReview();saveOpen.value=true}
async function confirmSave(){if(!saveOpen.value||props.active===false||editor.value)return;if(!models.fileDirty){saveOpen.value=false;return}if(reviewBase!==currentReview()){models.fileError='保存预览已过期，当前输入已保留，请重新核对。';return}saveOpen.value=false;await models.saveChannels(saveScope.value);if(models.fileError)useFeedbackStore().showToast('未写入：'+models.fileError,{kind:'error'});else useModelSaveFeedback().showSaved()}
const isActive=()=>props.active!==false
async function saveDetail(){const channel=editor.value;if(!channel||!isActive()||models.fileBusy||!models.canSaveFile||!models.channelDirty(channel.id)||channelNameErrorV2(channel.label,channel.id,models.channels)||protectedChannel(channel))return;const id=channel.id;await models.saveChannels(id);if(models.fileError){useFeedbackStore().showToast('未写入：'+models.fileError,{kind:'error'});return}useModelSaveFeedback().showSaved();if(isActive()&&models.channelEditorId===id&&!models.channelDirty(id))models.channelEditorId=''}
watch(()=>[models.channelEditorId,props.active],()=>{saveOpen.value=false})
function discardLocal(){const context=JSON.stringify({file:models.fileContext(),rows:models.modelRows});useModalStore().open({title:'放弃本次全部未保存更改',body:'确认后还原本次所有未保存的渠道修改，包括连接、模型选择及 API Key。已保存的配置与模版不受影响。',confirmLabel:'确认放弃全部更改',onConfirm:async()=>{if(context!==JSON.stringify({file:models.fileContext(),rows:models.modelRows})){models.fileError='放弃确认已过期，当前输入保持。';return}await models.discardChannels()}})}
function selectVisibleChannels(checked:boolean){const visible=new Set(filtered.value.map(c=>c.id));selectedChannelIds.value=checked?[...new Set([...selectedChannelIds.value,...visible])]:selectedChannelIds.value.filter(id=>!visible.has(id))}
async function editChannel(id:string){if(props.active===false)return;if(models.file?.draft){models.channelEditorId=id;return}if(await models.beginChannelSession())models.channelEditorId=id}
async function addChannel(){if(props.active!==false&&await models.beginChannelSession())newChannelOpen.value=true}
async function enableChannel(id:string,event:Event){const input=event.target as HTMLInputElement,value=input.checked;if(props.active!==false&&await models.beginChannelSession())models.queueChannel({kind:'set_enabled',channelId:id,enabled:value});else input.checked=models.channels.find(c=>c.id===id)?.connection.enabled??false}
function openCopy(id:string){reuseCopyKey.value=false;copyId.value=id;copyName.value=(models.channels.find(c=>c.id===id)?.label??'渠道')+' 副本';copyError.value=''}
async function confirmCopy(){if(models.fileBusy)return;const error=channelNameErrorV2(copyName.value,'',models.channels);if(error){copyError.value=error;return}try{if(!await models.beginChannelSession())return;const id=await models.copyChannel(copyId.value,copyName.value.trim(),reuseCopyKey.value);copyId.value='';models.channelEditorId=id}catch{copyError.value='副本尚未建立；当前名称和原件保持，请重新核对源渠道与凭据。'}}
async function confirmDelete(){if(models.fileBusy||!deleteId.value||!models.channelCapabilities.delete||!models.channelCapabilities.scopedSave)return;if(!await models.beginChannelSession())return;models.queueChannel({kind:'delete',channelId:deleteId.value});await models.saveChannels(deleteId.value);if(!models.fileError){deleteId.value='';models.channelEditorId=''}}
onMounted(()=>{if(props.active!==false&&!models.file)void models.loadChannels()})
</script>
<template>
  <section class="channels-v2" aria-label="渠道模型配置">
    <p v-if="models.fileError" role="alert" class="model-error">{{models.fileError}}</p>
    <p v-if="models.fileBusy" role="status">正在读取渠道配置…</p>
    <FileSourceReview />
    <Teleport defer :to="actionsTarget||'body'" :disabled="!actionsTarget"><div v-if="!editor" class="channel-policy-actions" aria-label="渠道配置保存状态"><span class="tag" role="status">{{models.fileDirty||models.pendingRows.length?'待保存修改':'未修改'}}</span><UiButton :disabled="models.fileBusy||!models.fileDirty&&!models.pendingRows.length" @click="discardLocal">还原修改</UiButton><UiButton variant="primary" data-testid="policy-save" :disabled="props.active===false||!!editor||!models.canSaveFile||!models.fileDirty||!!nameErrors.length||!!models.pendingRows.length" @click="prepareSave()">保存配置</UiButton></div></Teleport>
    <ChannelEditor v-if="editor" :channel="editor" :channels="models.channels" :effective="models.effectiveRows" :busy="models.fileBusy" :dirty="models.channelDirty(editor.id)" :save-disabled="props.active===false||!models.canSaveFile||!models.channelDirty(editor.id)||models.pendingRows.some(row=>row.channel===editor!.id)" @close="models.channelEditorId=''" @save="saveDetail" @intent="models.queueChannel" @edit="models.queueModel" />
    <template v-else>
      <div class="channel-list-toolbar"><input v-model="models.channelSearch" class="input" type="search" aria-label="搜索渠道" placeholder="搜索渠道名称或标识" /><div class="channel-list-actions"><UiButton :disabled="models.fileBusy||!models.file" @click="models.readExisting">读取现有渠道</UiButton><UiButton :disabled="models.fileBusy||!models.file" @click="importOpen=true">导入配置</UiButton><UiButton variant="primary" :disabled="models.fileBusy||!models.file" @click="addChannel">新增渠道</UiButton><details class="channel-more"><summary class="btn" aria-label="更多渠道操作">更多</summary><div class="channel-more-actions"><UiButton :disabled="models.fileBusy||!models.file||!!models.channelIntents.length||!!models.modelEdits.length" @click="pickerOpen=true">预览当前模型目录</UiButton><UiButton :loading="models.fileBusy" :disabled="models.fileBusy" @click="models.loadChannels()">刷新当前快照</UiButton></div></details></div></div>
      <div class="model-table-scroll"><table class="model-table"><thead><tr><th><input type="checkbox" aria-label="选择当前渠道结果" :checked="filtered.length>0&&filtered.every(c=>selectedChannelIds.includes(c.id))" :indeterminate="filtered.some(c=>selectedChannelIds.includes(c.id))&&!filtered.every(c=>selectedChannelIds.includes(c.id))" @change="selectVisibleChannels(($event.target as HTMLInputElement).checked)" /></th><th>渠道</th><th>模型</th><th>启用</th><th>操作</th></tr></thead><tbody><tr v-for="channel in filtered" :key="channel.id"><td><input v-model="selectedChannelIds" type="checkbox" :value="channel.id" :aria-label="'选择渠道 '+channel.label" /></td><td><strong>{{channel.label}}</strong><small>{{channel.id}}</small><small>{{channel.connection.nodes.find(n=>n.id===channel.connection.activeNodeId)?.name??'无当前节点'}} · {{channel.connection.nodes.find(n=>n.id===channel.connection.activeNodeId)?.url??'未配置'}}</small></td><td>已选 {{channel.selection.mode==='all'?channel.models.length:channel.selection.mode==='whitelist'?channel.selection.models.length:0}} / {{channel.models.length}}</td><td><label><input type="checkbox" :aria-label="'启用渠道 '+channel.label" :checked="channel.connection.enabled" :disabled="models.fileBusy||protectedChannel(channel)" @change="enableChannel(channel.id,$event)" />{{channel.connection.enabled?'已启用':'已停用'}}</label></td><td><div class="model-inline"><UiButton size="sm" :disabled="models.fileBusy" @click="editChannel(channel.id)">编辑</UiButton><UiButton size="sm" class="channel-node-detect" :aria-label="'检测 '+channel.label+' 服务节点'" aria-haspopup="dialog" :aria-expanded="nodeOpenId===channel.id" :disabled="props.active===false||!channel.connection.nodes.length" @click="nodeOpenId=channel.id">检测</UiButton><UiButton size="sm" :disabled="models.fileBusy||protectedChannel(channel)||!models.channelCapabilities.copy" title="复制到草稿，由后端保全同源凭据" @click="openCopy(channel.id)">复制</UiButton><UiButton size="sm" :disabled="models.fileBusy||protectedChannel(channel)||!models.channelCapabilities.delete||!models.channelCapabilities.scopedSave" @click="deleteId=channel.id">删除</UiButton></div></td></tr></tbody></table></div>
      <p v-if="models.file&&!models.channels.length&&!models.fileBusy" class="model-muted">暂无渠道。可读取现有渠道，或新增渠道。</p>
      <p v-if="!models.file&&!models.fileBusy" class="model-muted">尚未读取渠道配置，请重试。</p>
    </template>
    <ModelPicker :open="pickerOpen" :rows="[]" :v2-rows="models.file?.effective" :channels="models.channels.map(c=>({id:c.id,label:c.label,providerId:c.connection.providerId}))" title="当前模型目录" @close="pickerOpen=false" @confirm="pickerOpen=false" />
    <NewChannelDialog v-if="newChannelOpen" @close="newChannelOpen=false" @added="models.channelEditorId=$event" />
    <ChannelNodeSelect v-for="channel in models.channels" :key="channel.id" :channel="channel" :expected="models.file?.draft?.base" :open="nodeOpenId===channel.id" :show-trigger="false" :active="props.active!==false&&!editor&&filtered.some(c=>c.id===channel.id)" :readonly="protectedChannel(channel)||models.fileBusy||!models.channelCapabilities.activeNode" :measurement-disabled="protectedChannel(channel)||models.fileBusy||!models.channelCapabilities.measure" @close="nodeOpenId=''" @select="models.queueChannel({kind:'set_active_node',channelId:channel.id,nodeId:$event})" />
    <NativeConfigImportDialog :open="importOpen" @close="importOpen=false" />
    <UiDialog :open="!!copyId" title="复制渠道到草稿" :busy="models.fileBusy" @close="copyId=''">
      <p>复制当前服务端渠道来源、模型人工设置及精确引用。新管理身份和运行键由后端生成，默认不复用源 Key；正式配置需后续保存。</p><label>新渠道名称<input v-model="copyName" class="input" aria-label="复制渠道名称" :disabled="models.fileBusy" /></label><label><input v-model="reuseCopyKey" type="checkbox" :disabled="models.fileBusy" aria-label="复用源渠道Key" />明确复用源渠道 Key（含本次待保存替换或清空意图）</label><p v-if="copyError" class="model-error" role="alert">{{copyError}}</p>
      <template #actions="{close}"><UiButton :disabled="models.fileBusy" @click="close">取消</UiButton><UiButton variant="primary" :disabled="models.fileBusy||!models.channelCapabilities.copy" @click="confirmCopy">确认复制到草稿</UiButton></template>
    </UiDialog>
    <UiDialog :open="!!deleteId" title="确认删除渠道" :busy="models.fileBusy" @close="deleteId=''">
      <p>将删除 {{models.channels.find(c=>c.id===deleteId)?.label}}，并由同一事务核对该渠道及受影响引用。其他渠道草稿保留；失败保留原件。</p><p v-if="models.fileError" class="model-error" role="alert">{{models.fileError}}</p>
      <template #actions="{close}"><UiButton :disabled="models.fileBusy" @click="close">取消</UiButton><UiButton variant="danger" :disabled="models.fileBusy||!models.channelCapabilities.delete||!models.channelCapabilities.scopedSave" @click="confirmDelete">确认删除渠道</UiButton></template>
    </UiDialog>
    <UiDialog :open="saveOpen" :title="saveScope?'保存当前渠道':'保存当前渠道草稿'" wide :busy="models.fileBusy" @close="saveOpen=false">
      <p>{{saveScope?'本次只提交当前渠道，其他草稿保留。':'本次提交当前服务端草稿及以下明确编辑。'}}渠道名、运行键与模型配置由同一事务核对；未确认前不写正式配置。</p>
      <p v-if="models.fileError" role="alert" class="model-error">{{models.fileError}}</p>
      <ul><li v-for="channel in models.channels.filter(c=>(!saveScope||c.id===saveScope)&&JSON.stringify(c)!==JSON.stringify(models.file?.savedPolicy.channels.find(saved=>saved.id===c.id)))" :key="channel.id">{{channel.label}} · 有草稿变化</li><li v-for="(intent,index) in models.channelIntents.filter(i=>!saveScope||i.channelId===saveScope)" :key="'c'+index">{{models.channels.find(c=>c.id===intent.channelId)?.label??intent.channelId}} · {{intent.kind==='rename'?'名称 / 实际运行键':intent.kind==='set_enabled'?'启停':intent.kind==='set_selection'?'模型公开范围':intent.kind==='set_order'?'模型顺序':intent.kind==='set_defaults'?'非协议渠道默认':intent.kind==='set_family_defaults'?'非协议族设置':intent.kind==='set_naming'?'模型命名':intent.kind==='set_template_refs'?'精确模版候选':intent.kind==='set_active_node'?'当前服务节点':'删除渠道'}}</li><li v-for="(action,id) in models.pendingCredentialKinds" v-show="!saveScope||id===saveScope" :key="'key'+id">{{models.channels.find(c=>c.id===id)?.label??id}} · API Key · {{action==='clear'?'明确清空':'明确替换'}}</li><li v-for="(edit,index) in models.modelEdits.filter(e=>!saveScope||e.channelId===saveScope)" :key="'m'+index">{{edit.rawModelId}} · {{'field'in edit?edit.field:'明确模版引用'}} · {{edit.kind==='clear_override'?'恢复继承':'明确人工设置'}}</li></ul>
      <p v-if="!models.fileDirty" class="model-muted">没有待保存修改；明确详情保存仍会核对名称与运行键。</p>
      <template #actions="{close}"><UiButton :disabled="models.fileBusy" @click="close">取消</UiButton><UiButton variant="primary" :disabled="!models.canSaveFile||!!nameErrors.length" :loading="models.fileBusy" @click="confirmSave">确认保存</UiButton></template>
    </UiDialog>
  </section>
</template>
<style scoped>
.channels-v2{display:grid;gap:var(--space-4);min-width:0}.channels-v2 .model-table-scroll{overflow:auto}.channels-v2 table{width:100%;min-width:660px}.channels-v2 th,.channels-v2 td{padding:12px;text-align:left;vertical-align:top;border-bottom:1px solid var(--border)}.channels-v2 small{display:block;overflow-wrap:anywhere;color:var(--muted)}.channels-v2 label{display:flex;gap:var(--space-2);align-items:center}.channels-v2 li{overflow-wrap:anywhere}
.channel-policy-actions,.channel-list-toolbar,.channel-list-actions{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap;min-width:0}.channel-policy-actions{justify-content:flex-end}.channel-list-toolbar{justify-content:space-between;margin:6px 0 0;gap:var(--space-3)}.channel-list-toolbar>.input{flex:1 1 180px;max-width:360px;min-width:100px}.channel-list-actions{margin-inline-start:auto;justify-content:flex-end}.channel-more{position:relative}.channel-more>summary{list-style:none;cursor:pointer}.channel-more>summary::-webkit-details-marker{display:none}.channel-more-actions{position:absolute;right:0;top:calc(100% + 4px);z-index:5;display:grid;gap:var(--space-2);min-width:180px;padding:var(--space-2);border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--panel);box-shadow:var(--shadow)}.channel-more-actions>button{white-space:nowrap;justify-content:flex-start}
</style>
